def shortest_path(graph, source, target):
    if source == target:
        return (0, [source])  # If source and target are the same, the path is trivial and has zero edges.

    visited = set()
    queue = [(source, [source])]

    while queue:
        current, path = queue.pop(0)

        if current == target:
            return (len(path) - 1, path)  # "-1" because of the node at the start of the path.

        if current not in visited:
            visited.add(current)
            for neighbor in graph.get(current, []):
                if neighbor not in visited:
                    queue.append((neighbor, path + [neighbor]))

    return (float("inf"), None)  # If target is unreachable.
